def power(base, n):
    if n == 0:
        return 1
    half = power(base, n // 2)
    if n % 2 == 0:
        return half * half
    return base * half * half

values = [2, 3, 5]
totals = []
for i in range(len(values)):
    totals.append(power(values[i], 7))
print(totals)
print(totals[0] + totals[1] + totals[2])

